-- =============================================================================
-- FoT-AMS  AUDIT of an EXISTING database   (READ-ONLY)
--
-- Run this BEFORE and AFTER the upgrade, on the database you want to check:
--   mysql -u <user> -p faculty_ams -e "source database/audit_existing_database.sql"
--
-- What it checks: required tables and columns, migration history, duplicate keys, orphaned foreign-key
-- values, role/subtype consistency, enrollment and course consistency, attendance and medical consistency,
-- and mark / grade / GPA consistency. The assignment-specific counts and scenarios are in
-- database/verify_assignment_data.sql.
--
-- Output: ONE result set with the columns  check_name | status | detail
--   PASS  the check found nothing wrong / the requirement is met
--   FAIL  a rule is broken (fix the data or the schema; see README, Recovery)
--   WARN  suspicious or incomplete; needs a human decision
--   INFO  a count or listing, no judgement
--   SKIP  the check was NOT run because a table or column it needs does not exist
-- A missing table or column never stops the script: the dependent checks are reported as SKIP.
--
-- READ-ONLY: only SELECT statements and session variables (@q1, @sql ...). Nothing is created, changed,
-- locked or deleted, no temporary table and no special privilege is needed (SELECT on the schema).
-- It reads the database it is run against; it says nothing about any other copy of the data.
-- =============================================================================

USE faculty_ams;

SET @q1 := 'SELECT ''00 scope'' AS check_name, ''INFO'' AS status, CONVERT(''Read-only structural and data audit of the database this script is run against (information_schema + SELECT).'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail';
SET @q2 := IF(1 = 1, 'SELECT ''01 table exists: departments'' AS check_name, IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ''departments'') = 1, ''PASS'', ''FAIL'') AS status, CONVERT(IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ''departments'') = 1, ''present'', ''MISSING - run database/schema.sql and the migrations'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail', 'SELECT ''01 table exists: departments'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: -'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q3 := IF(1 = 1, 'SELECT ''01 table exists: users'' AS check_name, IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ''users'') = 1, ''PASS'', ''FAIL'') AS status, CONVERT(IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ''users'') = 1, ''present'', ''MISSING - run database/schema.sql and the migrations'') USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail', 'SELECT ''01 table exists: users'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: -'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
