SET @q19 := IF(1 = 1, 'SELECT ''01 tables left behind by the OLD migration 005 (*_other_module): their records were renamed away, not migrated'' AS check_name, IF(x.c = 0, ''PASS'', ''WARN'') AS status, CONVERT(CONCAT(x.c, '' table(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_NAME LIKE ''%\\_other\\_module'') AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT t.TABLE_NAME SEPARATOR '', ''), 1, 200) FROM information_schema.TABLES t WHERE t.TABLE_SCHEMA = DATABASE() AND t.TABLE_NAME LIKE ''%\\_other\\_module'') AS s) x', 'SELECT ''01 tables left behind by the OLD migration 005 (*_other_module): their records were renamed away, not migrated'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: -'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
