SET @q114 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('obtainMarks')) = 1, 'SELECT ''10 CA mark (obtainMarks) outside 0-100'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.obtainMarks < 0 OR m.obtainMarks > 100) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.obtainMarks < 0 OR m.obtainMarks > 100) AS s) x', 'SELECT ''10 CA mark (obtainMarks) outside 0-100'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(obtainMarks)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q115 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('finalMarks')) = 1, 'SELECT ''10 final mark (finalMarks) outside 0-100'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.finalMarks < 0 OR m.finalMarks > 100) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.finalMarks < 0 OR m.finalMarks > 100) AS s) x', 'SELECT ''10 final mark (finalMarks) outside 0-100'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(finalMarks)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q116 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('overall_mark')) = 1, 'SELECT ''10 overall mark outside 0-100'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.overall_mark < 0 OR m.overall_mark > 100) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.overall_mark < 0 OR m.overall_mark > 100) AS s) x', 'SELECT ''10 overall mark outside 0-100'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(overall_mark)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q117 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('grade_points')) = 1, 'SELECT ''10 grade points outside 0-4'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.grade_points < 0 OR m.grade_points > 4) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.grade_points < 0 OR m.grade_points > 4) AS s) x', 'SELECT ''10 grade points outside 0-4'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q118 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('grade', 'published')) = 2, 'SELECT ''10 published result without a grade'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.published = 1 AND (m.grade IS NULL OR m.grade = '''')) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.published = 1 AND (m.grade IS NULL OR m.grade = '''')) AS s) x', 'SELECT ''10 published result without a grade'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(grade, published)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q119 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('grade')) = 1, 'SELECT ''10 grade that is not in the grade table'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.grade IS NOT NULL AND m.grade NOT IN (''A+'', ''A'', ''A-'', ''B+'', ''B'', ''B-'', ''C+'', ''C'', ''C-'', ''D+'', ''D'', ''E'')) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.grade SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.grade IS NOT NULL AND m.grade NOT IN (''A+'', ''A'', ''A-'', ''B+'', ''B'', ''B-'', ''C+'', ''C'', ''C-'', ''D+'', ''D'', ''E'')) AS s) x', 'SELECT ''10 grade that is not in the grade table'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(grade)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q120 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('grade', 'grade_points')) = 2, 'SELECT ''10 grade without grade points / grade points without grade'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE (m.grade IS NULL) <> (m.grade_points IS NULL)) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE (m.grade IS NULL) <> (m.grade_points IS NULL)) AS s) x', 'SELECT ''10 grade without grade points / grade points without grade'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(grade, grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q121 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'marks' AND COLUMN_NAME IN ('grade', 'grade_points')) = 2, 'SELECT ''10 grade points that do not belong to the grade'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM marks m WHERE m.grade IS NOT NULL AND m.grade_points IS NOT NULL AND m.grade_points <> CASE m.grade WHEN ''A+'' THEN 4.0 WHEN ''A'' THEN 4.0 WHEN ''A-'' THEN 3.7 WHEN ''B+'' THEN 3.3 WHEN ''B'' THEN 3.0 WHEN ''B-'' THEN 2.7 WHEN ''C+'' THEN 2.3 WHEN ''C'' THEN 2.0 WHEN ''C-'' THEN 1.7 WHEN ''D+'' THEN 1.3 WHEN ''D'' THEN 1.0 WHEN ''E'' THEN 0.0 ELSE -1 END) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT m.marksid SEPARATOR '', ''), 1, 200) FROM marks m WHERE m.grade IS NOT NULL AND m.grade_points IS NOT NULL AND m.grade_points <> CASE m.grade WHEN ''A+'' THEN 4.0 WHEN ''A'' THEN 4.0 WHEN ''A-'' THEN 3.7 WHEN ''B+'' THEN 3.3 WHEN ''B'' THEN 3.0 WHEN ''B-'' THEN 2.7 WHEN ''C+'' THEN 2.3 WHEN ''C'' THEN 2.0 WHEN ''C-'' THEN 1.7 WHEN ''D+'' THEN 1.3 WHEN ''D'' THEN 1.0 WHEN ''E'' THEN 0.0 ELSE -1 END) AS s) x', 'SELECT ''10 grade points that do not belong to the grade'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: marks(grade, grade_points)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q122 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'component_marks' AND COLUMN_NAME IN ('eval_component_id', 'marks_obtained')) = 2 AND (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'evaluation_component' AND COLUMN_NAME IN ('eval_component_id', 'max_marks')) = 2, 'SELECT ''10 component mark above the component maximum'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM component_marks cm JOIN evaluation_component ec ON ec.eval_component_id = cm.eval_component_id WHERE cm.marks_obtained > ec.max_marks) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT cm.eval_component_id SEPARATOR '', ''), 1, 200) FROM component_marks cm JOIN evaluation_component ec ON ec.eval_component_id = cm.eval_component_id WHERE cm.marks_obtained > ec.max_marks) AS s) x', 'SELECT ''10 component mark above the component maximum'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: component_marks(eval_component_id, marks_obtained), evaluation_component(eval_component_id, max_marks)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q123 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'component_marks' AND COLUMN_NAME IN ('marks_obtained')) = 1, 'SELECT ''10 negative component mark'' AS check_name, IF(x.c = 0, ''PASS'', ''FAIL'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM component_marks cm WHERE cm.marks_obtained < 0) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT cm.eval_component_id SEPARATOR '', ''), 1, 200) FROM component_marks cm WHERE cm.marks_obtained < 0) AS s) x', 'SELECT ''10 negative component mark'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: component_marks(marks_obtained)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q124 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'evaluation_component' AND COLUMN_NAME IN ('course_id', 'weightage')) = 2, 'SELECT ''10 course whose component weightages do not add up to 100'' AS check_name, IF(x.c = 0, ''PASS'', ''WARN'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM (SELECT course_id FROM evaluation_component GROUP BY course_id HAVING ROUND(SUM(weightage), 2) <> 100) w) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT w.course_id SEPARATOR '', ''), 1, 200) FROM (SELECT course_id FROM evaluation_component GROUP BY course_id HAVING ROUND(SUM(weightage), 2) <> 100) w) AS s) x', 'SELECT ''10 course whose component weightages do not add up to 100'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: evaluation_component(course_id, weightage)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q125 := IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'evaluation_component' AND COLUMN_NAME IN ('max_marks')) = 1, 'SELECT ''10 component not marked out of 100 (assignment: marks out of 100)'' AS check_name, IF(x.c = 0, ''PASS'', ''WARN'') AS status, CONVERT(CONCAT(x.c, '' row(s)'', IFNULL(CONCAT('' (e.g. '', x.s, '')''), '''')) USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail FROM (SELECT (SELECT COUNT(*) FROM evaluation_component ec WHERE ec.max_marks <> 100) AS c, (SELECT SUBSTRING(GROUP_CONCAT(DISTINCT ec.component_name SEPARATOR '', ''), 1, 200) FROM evaluation_component ec WHERE ec.max_marks <> 100) AS s) x', 'SELECT ''10 component not marked out of 100 (assignment: marks out of 100)'' AS check_name, ''SKIP'' AS status, CONVERT(''not run - required table/column missing: evaluation_component(max_marks)'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail');
SET @q126 := 'SELECT ''10 grade table'' AS check_name, ''WARN'' AS status, CONVERT(''Grade bands are the ones coded in the application (AcademicRules / GradingScheme). They have NOT been checked against UGC Commission Circular No. 12-2024 - compare them with the circular.'' USING utf8mb4) COLLATE utf8mb4_unicode_ci AS detail';

